// Package store (pieces ⑬ and ⑭) owns the SQLite database: opening it with
// safe pragmas, running migrations after an automatic backup, and mapping
// rows to domain types. Queries are generated by sqlc into store/db.
package store

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"os"
	"path/filepath"
	"time"

	"github.com/pressly/goose/v3"
	_ "modernc.org/sqlite" // pure-Go SQLite driver (no cgo)

	"github.com/akamachinecode/exhale/internal/store/db"
)

//go:embed migrations/*.sql
var migrations embed.FS

// Store is the database handle.
type Store struct {
	DB  *sql.DB
	Q   *db.Queries
	dir string
}

// Open opens (or creates) the database in dataDir, backs it up if migrations
// are pending, and migrates it to the latest version.
func Open(ctx context.Context, dataDir string, log *slog.Logger) (*Store, error) {
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		return nil, fmt.Errorf("store: create data dir: %w", err)
	}
	path := filepath.Join(dataDir, "exhale.db")
	return open(ctx, "file:"+path, dataDir, log)
}

// OpenMemory opens a private in-memory database, for tests.
func OpenMemory(ctx context.Context) (*Store, error) {
	return open(ctx, fmt.Sprintf("file:mem%d?mode=memory&cache=shared", time.Now().UnixNano()), "", slog.New(slog.DiscardHandler))
}

func open(ctx context.Context, dsn, dir string, log *slog.Logger) (*Store, error) {
	sep := "?"
	if containsQuery(dsn) {
		sep = "&"
	}
	dsn += sep + "_pragma=busy_timeout(5000)&_pragma=foreign_keys(1)&_pragma=journal_mode(WAL)&_pragma=synchronous(NORMAL)"
	sqldb, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("store: open: %w", err)
	}
	// One connection serializes writers; the load is human-speed.
	sqldb.SetMaxOpenConns(1)
	s := &Store{DB: sqldb, Q: db.New(sqldb), dir: dir}
	if err := s.migrate(ctx, log); err != nil {
		sqldb.Close()
		return nil, err
	}
	return s, nil
}

func containsQuery(s string) bool {
	for _, c := range s {
		if c == '?' {
			return true
		}
	}
	return false
}

func (s *Store) migrate(ctx context.Context, log *slog.Logger) error {
	sub, err := fs.Sub(migrations, "migrations")
	if err != nil {
		return err
	}
	p, err := goose.NewProvider(goose.DialectSQLite3, s.DB, sub)
	if err != nil {
		return fmt.Errorf("store: migrations: %w", err)
	}
	cur, err := p.GetDBVersion(ctx)
	if err != nil {
		return fmt.Errorf("store: migration version: %w", err)
	}
	pending, err := p.HasPending(ctx)
	if err != nil {
		return fmt.Errorf("store: pending migrations: %w", err)
	}
	if !pending {
		return nil
	}
	var backup string
	if cur > 0 && s.dir != "" {
		backup, err = s.Backup(ctx, fmt.Sprintf("pre-migrate-v%d", cur))
		if err != nil {
			return fmt.Errorf("store: backup before migrating: %w", err)
		}
		log.Info("backed up database before migrating", "path", backup)
	}
	results, err := p.Up(ctx)
	if err != nil {
		if backup != "" {
			return fmt.Errorf("store: migration failed (restore from %s): %w", backup, err)
		}
		return fmt.Errorf("store: migration failed: %w", err)
	}
	for _, r := range results {
		log.Info("applied migration", "version", r.Source.Version, "duration", r.Duration)
	}
	return nil
}

// Backup writes a consistent snapshot of the database (VACUUM INTO) to
// <data>/backups/<name>-<timestamp>.db and returns its path.
func (s *Store) Backup(ctx context.Context, name string) (string, error) {
	if s.dir == "" {
		return "", errors.New("store: backups need a data directory")
	}
	dir := filepath.Join(s.dir, "backups")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", err
	}
	path := filepath.Join(dir, fmt.Sprintf("%s-%s.db", name, time.Now().UTC().Format("20060102T150405Z")))
	if _, err := s.DB.ExecContext(ctx, "VACUUM INTO ?", path); err != nil {
		return "", err
	}
	return path, nil
}

// Close closes the database.
func (s *Store) Close() error { return s.DB.Close() }

// Tx runs fn in a transaction. Returning an error rolls it back.
func (s *Store) Tx(ctx context.Context, fn func(q *db.Queries) error) error {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(s.Q.WithTx(tx)); err != nil {
		_ = tx.Rollback()
		return err
	}
	return tx.Commit()
}
